x1, y1, x2, y2 = -2.0, 1.0, 10.0, 7.0
xmin, xmax, ymin, ymax = 2.0, 8.0, 2.0, 6.0
dx, dy = x2 - x1, y2 - y1
u1, u2 = 0.0, 1.0
for p, q in ((-dx, x1 - xmin), (dx, xmax - x1),
             (-dy, y1 - ymin), (dy, ymax - y1)):
    if p == 0:
        if q < 0:
            u1, u2 = 1.0, 0.0
    else:
        r = q / p
        if p < 0:
            u1 = max(u1, r)
        else:
            u2 = min(u2, r)
print(round(x1 + u1 * dx))
print(round(y1 + u1 * dy))
print(round(x1 + u2 * dx))
print(round(y1 + u2 * dy))
